"""Render CASES.md from results/*/expected_check.json and inputs/*.expected.json.
Usage: math7-py -B code/make_cases_md.py"""
import json
from pathlib import Path
F = Path(__file__).resolve().parents[1]
ENG = ["SymPy", "NumPy", "mpmath", "SciPy", "F_Fraction", "F_mpmath60"]
lines = ["# CASES — restricted Math IR 0.1 cases run locally (5 Python engines)", "",
         "Generated by `code/make_cases_md.py` from `results/*/expected_check.json`. "
         "SageMath and MATLAB: **NOT_RUN** for every case. SciPy is `N/A` per case: Math7 "
         "runs one fixed x^2 quadrature reference, not a per-case computation. "
         "`F_Fraction` / `F_mpmath60` are route F's own evaluators (not Math7 engines). "
         "DuckDB is checked per unit group (table below each input).", ""]
for name in ["wlc_pilots_p0_p1_p2", "wlc_route_e_identities", "negative_wrong_expected"]:
    rep = json.loads((F / "results" / name / "expected_check.json").read_text())
    side = {e["case_id"]: e for e in json.loads((F / "inputs" / f"{name}.expected.json").read_text())}
    lines += [f"## `inputs/{name}.json` — overall **{rep['overall']}**", "",
              "| case id | identity | source file : key | expected | " + " | ".join(ENG) + " | verdict |",
              "|---|---|---|---|" + "---|" * len(ENG) + "---|"]
    for r in rep["cases"]:
        s = side[r["case_id"]]
        src = s["source"].split("WLC_CIRCUIT_RESEARCH/")[-1]
        lines.append(f"| `{r['case_id']}` | {s['identity']} | `{src}` : {s['key']} | {r['expected']} | "
                     + " | ".join(r["per_engine"][e] for e in ENG) + f" | **{r['verdict']}** |")
    lines += ["", "| DuckDB unit group | DuckDB exact sum | sum of expected | verdict |", "|---|---|---|---|"]
    for u, d in rep["duckdb_groups"].items():
        lines.append(f"| `{u}` | {d['duckdb_exact_sum']} | {d['expected_sum']} | {d['verdict']} |")
    lines += ["", "Case notes (what is NOT checked):", ""]
    for cid, s in side.items():
        if s.get("note"):
            lines.append(f"- `{cid}`: {s['note']}")
    lines.append("")
(F / "CASES.md").write_text("\n".join(lines))
print("wrote CASES.md")
